def parse_receipts(text):
    lines = text.splitlines()[1:]
    rows = []
    for line in lines:
        if not line.strip():
            continue
        invoice_id, item, amount = line.split(',')
        rows.append({'invoice_id': invoice_id, 'item': item, 'amount': float(amount)})
    return rows

