class Worker:
    def __init__(self, store, handler):
        self.store = store
        self.handler = handler

    def run_once(self):
        task = self.store.next_task()
        if task is None:
            return False
        task_id, payload = task
        self.handler(payload)
        self.store.ack(task_id)
        return True

